save(451,dict(paragraphs=["Manas Ranjan Mahapatra is an Odia poet, fiction writer, translator and editor whose literary life remains closely connected with Puri. His work at the National Book Trust included the National Centre for Children’s Literature. In a 2021 interview, he described editing as a commitment to other writers that also sharpened his scrutiny of his own work. His books include the story collection Unit Tinira Premika and the novel Nihsanga.","In ‘ଦିନେ ଫେରିବାବେଳେ ଅନ୍ଧାରରେ’, a friend’s warning about the dangers of walking home in darkness becomes an unexpected argument. The speaker answers that daylight holds wounds of its own, turning a familiar exchange into a terse meditation on human hurt. Its conversational opening and ironic reversal give a small scene a wider moral reach."],sources=[source('Odisha Sambad — interview with Manas Ranjan Mahapatra','https://odishasambad.in/literature-interview-with-manas-ranjan-mahapatra/',['Poetry/fiction/translation/editing; Puri connection; reflection on editing; Unit Tinira Premika and Nihsanga.']),source('National Book Trust — October 2013 newsletter','https://www.nbtindia.gov.in/writereaddata/attachment/tuesday-september-24-20134-15-46-pmnewsletter-oct-2013-for-web.pdf',['Manas Ranjan Mahapatra, Editor NCCL, coordinating children’s literature discussion.'],access='search_index_newsletter_excerpt'),source('Katha Utsav 2013 — Manas Ranjan Mahapatra','https://www.katha.org/kathautsav2013/ManasRanjanMahapatra.html',['Poet/editor and reading workshop; story collection and novel; translation work.'],access='search_index_event_record; direct retrieval failed')],identity_match='Puri literary connection, combination of poet/fiction/translator/editor work and book genres match supplied biography; Katha and NBT corroborate the literary professional, excluding physicist and legal namesakes.',poems_read=[dict(id=744,title='ଦିନେ ଫେରିବାବେଳେ ଅନ୍ଧାରରେ',basis='Full Odia text read: friend warns of ghosts/thieves/snakes at night; speaker contrasts crowded wounds of daylight and returns quietly to darkness.')],limitations=['Exact birth date and lifetime book totals not independently rechecked and omitted.','Interview honours not repeated as formal state awards; awards require awarding-body evidence.','Book-title romanisation is editorial; Odia titles and dates retained in source evidence, no new retail link verified.','NBT role is historical, not a present appointment.'],next_action='Independent author/editor review of narrative and preferred book-title romanisation.'))
